cd '/app/files/dc_model__hall_seed005_d100__mep_routing' || exit 1
cd /app/files/dc_model__hall_seed005_d100__mep_routing && python3 output/solution.py /tmp/work/test.ifc && python3 /tmp/work/validate.py /tmp/work/test.ifc && python3 /tmp/work/check.py /tmp/work/test.ifc 2>&1 | grep -E "CLASH|same-service|connected|separation|violations|row |contained|not contained" && python3 -c "
import ifcopenshell
f = ifcopenshell.open('/tmp/work/test.ifc')
print('ports', len(f.by_type('IfcDistributionPort')), 'conns', len(f.by_type('IfcRelConnectsPorts')), 'nests', len(f.by_type('IfcRelNests')))
import collections
# port-graph connectivity per system
for sysobj in f.by_type('IfcDistributionSystem'):
    segs = [e for r in sysobj.IsGroupedBy for e in r.RelatedObjects]
    owner = {}
    for s in segs:
        for r in s.IsNestedBy:
            for p in r.RelatedObjects: owner[p.id()] = s.id()
    adj = collections.defaultdict(set)
    for c in f.by_type('IfcRelConnectsPorts'):
        a, b = owner.get(c.RelatingPort.id()), owner.get(c.RelatedPort.id())
        if a and b: adj[a].add(b); adj[b].add(a)
    seen = {segs[0].id()}; st=[segs[0].id()]
    while st:
        u=st.pop()
        for v in adj[u]:
            if v not in seen: seen.add(v); st.append(v)
    print(sysobj.Name, 'segments', len(segs), 'port-connected', len(seen)==len(segs))
"
